// mobile-prebuild.mjs — REGENERATE THE PHONE APP'S NATIVE PROJECT WHEN WHAT IT IS MADE FROM CHANGED. `mobile/ios` and
// `mobile/android` are generated by `expo prebuild` and gitignored, and an existing one silently keeps the native
// modules it was generated with: a new one (expo-secure-store) then fails only at launch, as "Cannot find native
// module" and a white screen. Shared by android.mjs and ios.mjs.

import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/** A fingerprint of everything prebuild reads: the app's package.json, app.json and config plugins. */
function fingerprint() {
    const h = createHash("sha256");
    const files = ["mobile/package.json", "mobile/app.json", ...readdirSync("mobile/plugins").sort().map((f) => join("mobile/plugins", f))];
    for (const f of files) h.update(f).update(readFileSync(f));
    return h.digest("hex");
}

/**
 * Make sure `mobile/<platform>` matches its inputs: generate it when missing, regenerate it from scratch (`--clean`)
 * when the fingerprint changed. `run` is the caller's command runner. True when it (re)generated, so the caller knows
 * to redo what follows from a fresh project (iOS: `pod install`).
 */
export function ensurePrebuild(platform, run) {
    const stamp = `mobile/${platform}/.wml-prebuild`;
    const want = fingerprint();
    if (existsSync(stamp) && readFileSync(stamp, "utf8") === want) return false;
    const clean = existsSync(`mobile/${platform}`) ? ["--clean"] : [];
    run("npx", ["expo", "prebuild", "--platform", platform, "--no-install", ...clean], { cwd: "mobile" });
    writeFileSync(stamp, want);
    return true;
}
